// 기기 지원 여부는 초기화 전에 따로 묻는다 (throw 없음)
switch OneS1ght.deviceAvailability {
case .deviceNotSupported: markPositioningUnavailable()   // 화면은 계속 쓴다
case .osVersionTooLow:    markOsTooLow()
case .available:          break
}

do {
    try await OneS1ght.initialize(sdkKey: key)   // 키·설정만 확인한다
} catch {
    showError(error)
}

// 미지원 기기에서도 여기까지 온다 — 지도와 존은 그려도 된다
let buildings = try await OneS1ght.buildings()
let floor = try await OneS1ght.floor(buildingId, floorId)
let zones = try await OneS1ght.zones(buildingId, floorId)

do {
    try await OneS1ght.floorSession().begin()
} catch SdkError.deviceNotSupported {
    // 이 기기는 UWB 가 없다 — 측위만 끄고 나머지 화면은 그대로 둔다
    markPositioningUnavailable()
} catch SdkError.osVersionTooLow {
    markOsTooLow()
}

